   Assert(!profile.Tested,"Recording starts untested");await Throws(()=>Task.Run(()=>profile.Validate(true)),"Untested profile rejected for ISO");
   using(var timeout=new CancellationTokenSource(TimeSpan.FromSeconds(30))){var logs=new List<string>();var code=await UiAutomationEngine.Replay(profile,exe,s=>{logs.Add(s);Console.WriteLine(s);},timeout.Token);Assert(code==0&&File.ReadAllText(marker)=="enabled|recorded-value|Test-Kennwort-123","Fresh real process replays selections and explicit password");Assert(!logs.Any(x=>x.Contains(secret.Value)),"Secret value excluded from replay log");}
   profile.Tested=true;profile.TestedPlanSha256=profile.PlanHash();profile.Validate(true);Assert(true,"Unchanged tested plan accepted");text.Value="modified";await Throws(()=>Task.Run(()=>profile.Validate(true)),"Changed tested plan invalidates approval");text.Value="recorded-value";
   await Throws(()=>UiAutomationEngine.Replay(profile,exe,_=>{},CancellationToken.None),"Existing proof file cannot falsely confirm a fresh installation");File.Delete(marker);
   var hash=profile.InstallerSha256;profile.InstallerSha256=new string('0',64);await Throws(()=>UiAutomationEngine.Replay(profile,exe,_=>{},CancellationToken.None),"Mismatched installer rejected before start");profile.InstallerSha256=hash;
   var old=text.AutomationId;text.AutomationId="does-not-exist";text.TimeoutSeconds=1;await Throws(()=>UiAutomationEngine.Replay(profile,exe,_=>{},CancellationToken.None),"Missing UI target times out instead of blind clicking");text.AutomationId=old;text.TimeoutSeconds=45;
   var config=XDocument.Parse(SandboxSessions.Config(@"C:\Input Ä & files",@"C:\Output",false));Assert(config.Descendants("ReadOnly").Select(x=>x.Value).SequenceEqual(new[]{"true","false"}),"Sandbox input read-only and isolated output writable");Assert(config.Root!.Element("Networking")!.Value=="Disable"&&config.Root.Element("ClipboardRedirection")!.Value=="Disable","Sandbox network and clipboard disabled by default");
   var outsideMarker=Path.Combine(directory,"outside.txt");using(var outside=UiAutomationEngine.StartInstaller(exe,"--fixture "+IsoBuilder.Quote(outsideMarker))){try{AutomationElement? outsideWindow=null;var deadline=DateTime.UtcNow.AddSeconds(20);while(DateTime.UtcNow<deadline){outsideWindow=AutomationElement.RootElement.FindAll(TreeScope.Children,new PropertyCondition(AutomationElement.ProcessIdProperty,outside.Id)).Cast<AutomationElement>().FirstOrDefault();if(outsideWindow!=null)break;await Task.Delay(200);}if(outsideWindow==null)throw new Exception("External fixture window missing");var outsideButton=outsideWindow.FindFirst(TreeScope.Descendants,new PropertyCondition(AutomationElement.AutomationIdProperty,"finish"));var outsideStep=UiAutomationEngine.Capture(outsideButton)!;UiAutomationEngine.BindExternal(outsideStep,outside.Id);Assert(!allowed(outside.Id)&&UiAutomationEngine.Find(outsideStep,allowed)==null,"Unrelated real process excluded from installer recording");var connected=UiAutomationEngine.Find(outsideStep,pid=>allowed(pid)||UiAutomationEngine.MatchesExternal(outsideStep,pid))!;UiAutomationEngine.Apply(connected,outsideStep);await outside.WaitForExitAsync();Assert(File.ReadAllText(outsideMarker)=="disabled|initial","Explicitly connected separate process dialog actually invoked");}finally{if(!outside.HasExited)outside.Kill(true);}}
   Assert(new SandboxFeature{Edition="Professional",State=2,Hypervisor=true}.Status.Contains("deaktiviert"),"Sandbox feature status distinguishes disabled component");await Throws(()=>Task.Run(()=>new SandboxFeature{Edition="Core",State=2}.ValidateActivation()),"Unsupported Home edition refuses feature activation");await Throws(()=>Task.Run(()=>new SandboxFeature{Edition="Professional",State=2,FirmwareVirtualization=false}.ValidateActivation()),"Disabled firmware virtualization refuses feature activation");
   var source=Path.Combine(directory,"profile.json");await profile.Save(source);var library=Path.Combine(directory,"Library");var entry=await RecordingLibrary.Store(source,"Testprogramm",library);File.Delete(source);Assert(File.Exists(entry.Path)&&entry.Tested&&entry.HasSecrets,"Library persists tested secret profile independently of session");var entries=await RecordingLibrary.List(library);Assert(entries.Count==1&&entries[0].HasSecrets,"Library reload preserves confidentiality status");var app=new Installer{Name="Fixture",Path=exe};await RecordingLibrary.Attach(app,entry);Assert(app.RecordedProfilePath==entry.Path&&app.Context=="User"&&app.AutomationMode=="Recorded","Saved recording attaches to matching installer");var mismatch=entry with{InstallerSha256=new string('0',64)};await Throws(()=>RecordingLibrary.Attach(app,mismatch),"Library rejects different installer version");
   var draft=new RecordedProfile{InstallerSha256=profile.InstallerSha256,DisplayName="Mein eigener Name"};var output=Path.Combine(directory,"Output");var draftHash=await SessionExports.Save(draft,output);var draftEntry=await RecordingLibrary.Store(Path.Combine(output,"profile.json"),"Fallback",library);Assert(draftEntry.Name=="Mein eigener Name"&&!draftEntry.Tested,"Named draft without proof or finished installer persists");await Throws(()=>Task.Run(()=>draft.Validate(true)),"Draft cannot be injected as verified installation");Assert(!await SessionExports.Accepted(output,draftHash),"Sandbox close requires host acknowledgement");await File.WriteAllTextAsync(Path.Combine(output,"accepted.txt"),draftHash);Assert(await SessionExports.Accepted(output,draftHash),"Exact saved profile acknowledgement accepted");draft.DisplayName="Neuer Name";var changedHash=await SessionExports.Save(draft,output);Assert(!await SessionExports.Accepted(output,changedHash),"Old acknowledgement does not accept changed recording name");var renamed=await RecordingLibrary.Store(Path.Combine(output,"profile.json"),"Fallback",library);Assert(renamed.Name=="Neuer Name","Renamed draft replaces stale display name");
   if(!SandboxSessions.GuestRunning){var cleanup=Path.Combine(SandboxSessions.Root,"Test-"+Guid.NewGuid());Directory.CreateDirectory(Path.Combine(cleanup,"Input"));File.WriteAllBytes(Path.Combine(cleanup,"Input","large-fixture.bin"),new byte[1024]);Assert(SandboxSessions.Cleanup(cleanup)&&!Directory.Exists(cleanup)&&File.Exists(entry.Path),"Session copies deleted while persistent profile remains");await Throws(()=>Task.Run(()=>SandboxSessions.Cleanup(directory)),"Cleanup refuses directories outside session root");}
   Console.WriteLine($"{passed} automation checks passed. Only the own harmless test window was executed.");return 0;
  }finally{if(process is {HasExited:false})process.Kill(true);process?.Dispose();Directory.Delete(directory,true);}
 }
